/**
 * MA two interior footpoints, A of degree 3 (implicit form coefficients `v`), B cubic:
 * returns `[a, b, e]` with `a[k][i]` (`b[k][i]`) the coefficient of `σ^i` in `aₖ` (`bₖ`)
 * where `f₂^eₖ·Gₖ ≡ aₖ·π + bₖ (mod F)`; with `e = max eₖ`, `a = Σ vₖf₂^(e-eₖ)aₖ` and
 * similarly `b`, the resultant is `(f₂b² - f₁ab + f₀a²)/f₂^e`
 * (232726 terms; multiplications: 7828486 without sharing,
 * 306481 with 68111 shared products)
 */
function maiAB_A3B3(bx: number[], by: number[]): [number[][], number[][], number[]] {
    const o = evalProgram2(P, [bx[2], bx[3], by[2], by[3]]);
    const a: number[][] = [];
    const b: number[][] = [];
    let i = 0;
    for (const n of [22, 22, 22, 22, 17, 17, 17, 12, 12, 7]) { a.push(Array.from(o.subarray(i, i += n))); }
    for (const n of [23, 23, 23, 23, 18, 18, 18, 13, 13, 8]) { b.push(Array.from(o.subarray(i, i += n))); }
    return [a, b, [8, 8, 8, 8, 6, 6, 6, 4, 4, 2]];
}


